MERGE INTO ONEX_WINDOW_REGISTRY t USING (SELECT '222INVT011.fmx' legacy_form FROM dual) s ON (t.LEGACY_FORM=s.LEGACY_FORM) WHEN MATCHED THEN UPDATE SET t.DOMAIN_CODE='ADMIN', t.CORE_CAPABILITY='ADMIN_SETUP', t.MIGRATION_PHASE=0 WHEN NOT MATCHED THEN INSERT (LEGACY_FORM,DOMAIN_CODE,CORE_CAPABILITY,MIGRATION_PHASE) VALUES ('222INVT011.fmx','ADMIN','ADMIN_SETUP',0);
